try {
  const raw = $input.first().json.candidates[0].content.parts[0].text;
  const parsed = JSON.parse(raw.trim());
  return [{ json: { success: true, aiGenerated: true, ...parsed } }];
} catch (e) {
  const orig = $('Prepare AI Prompt').first().json.originalInput;
  return [{ json: {
    success: true,
    aiGenerated: false,
    severityLevel: "HIGH",
    urgencyClassification: orig.incidentType || "SERVICE_DISRUPTION",
    emergencyHeadline: orig.headline || "Urgent Notice: Temporary Infrastructure Advisory",
    sanitizedBroadcastMessage: orig.details || "Facility management is actively addressing the matter. Safe operations expected shortly.",
    actionableDos: ["Follow facility team instructions", "Keep entry corridors clear"],
    actionableDonts: ["Do not spread unverified rumors", "Avoid panic calls to security"],
    expectedResolutionEtaMinutes: 45,
    escalationHelpline: "+91-98800-MANA-SOS",
    auditTimestamp: new Date().toISOString()
  } }];
}
